require_once dirname(__DIR__,2).'/config.php';require_once BASE_PATH.'/shared/marketing.php';marketing_require_access();
$id=max(0,(int)($_GET['id']??0));$params=[$id];$where='m.id=?';if(!marketing_is_owner()){$where.=' AND (m.entered_by=? OR EXISTS(SELECT 1 FROM marketing_campaigns c WHERE c.id=m.campaign_id AND c.assigned_employee_id=?) OR EXISTS(SELECT 1 FROM marketing_work_items w WHERE w.id=m.content_id AND w.assigned_employee_id=?) OR EXISTS(SELECT 1 FROM marketing_ads a WHERE a.id=m.ad_id AND a.assigned_employee_id=?))';array_push($params,marketing_employee_id(),marketing_employee_id(),marketing_employee_id(),marketing_employee_id());}$q=db()->prepare("SELECT m.* FROM marketing_metric_snapshots m WHERE $where LIMIT 1");$q->execute($params);$file=$q->fetch();if(!$file||empty($file['evidence_file'])){http_response_code(404);exit('Evidence not found.');}$base=realpath(BASE_PATH.'/uploads/marketing/metrics');$path=realpath(BASE_PATH.'/uploads/marketing/metrics/'.$file['evidence_file']);if(!$base||!$path||strpos($path,$base.DIRECTORY_SEPARATOR)!==0||!is_file($path)){http_response_code(404);exit('Evidence not found.');}header('Content-Type: '.($file['evidence_mime']?:'application/octet-stream'));header('Content-Length: '.filesize($path));header('Content-Disposition: inline; filename="'.rawurlencode((string)$file['evidence_name']).'"');header('X-Content-Type-Options: nosniff');readfile($path);
